	// Whether every sound made by a follower (a pet) is muted, cached from the config on each change
	private boolean mutePetFollowers;

	// Object ids that only spawn inside a player owned house
	private static final Set<Integer> POH_PET_HOUSE_OBJECTS = ImmutableSet.of(
		ObjectID.POH_MENAGERIE_PETHOUSE_HOTSPOT,
		ObjectID.POH_MENAGERIE_PETHOUSE_1,
		ObjectID.POH_MENAGERIE_PETHOUSE_2,
		ObjectID.POH_MENAGERIE_PETHOUSE_3,
		ObjectID.POH_MENAGERIE_PETHOUSE_4,
		ObjectID.POH_MENAGERIE_PETHOUSE_5,
		ObjectID.POH_MENAGERIE_PETHOUSE_6
	);

	// Set once a pet house object spawns, reset when a new scene starts loading
	private boolean isInPoh;

	// The user's custom "sounds to mute" list, parsed once per config change
	private Set<Integer> selectedSounds = Collections.emptySet();

	@Getter(AccessLevel.PUBLIC)
	public HashSet<SoundEffect> ambientSoundsToMute = new HashSet<>();

	// The same effects as ambientSoundsToMute, grouped by sound id
	private Map<Integer, List<AmbientSoundEffect>> ambientSoundsToMuteById = new HashMap<>();

	// Ids (AmbientSoundID) of the location based ambient sounds, set by the server, that get muted whole
	private Set<Integer> newAmbientSoundsToMute = new HashSet<>();

	private final List<net.runelite.api.AmbientSoundEffect> soundsToKeep = new ArrayList<>();

	// What the server set ambient sound looked like before "Muted Sounds" ids were taken out of it
	private final Map<RandomSound, int[]> originalRandomSoundIds = new IdentityHashMap<>();
	private final Map<List<RandomSound>, List<RandomSound>> originalRandomSoundLists = new IdentityHashMap<>();

	int currentPlayerRegionId = -1;

	@Provides
	AnnoyanceMuteConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AnnoyanceMuteConfig.class);
	}

	@Override
	public void startUp()
	{
		setUpMutes();
		reloadScene();
	}

	@Override
	public void shutDown()
	{
		isInPoh = false;
		soundEffects.clear();
		soundEffectsById.clear();
		clientThread.invoke(this::restoreAmbientSoundRandomSounds);
		reloadScene();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged configChanged)
	{
		if (configChanged.getGroup().equals("annoyancemute"))
		{
			setUpMutes();

			switch (configChanged.getKey())
			{
				case "muteMagicTrees":
				case "muteHousePortal":
				case "muteWhiteNoise":
				case "muteChirps":
				case "muteWater":
				case "muteRanges":
				case "muteFortisColosseum":
				case "muteStranglewoodHowls":
				case "ambientSoundsToMute":
				case "ambientSoundsToMuteRegional":
					reloadScene();
					break;
				case "soundsToMute":
					// put the removed ambient sounds back, then take out the new selection
					clientThread.invoke(() ->
					{
						restoreAmbientSoundRandomSounds();
						muteAmbientSounds();
					});
					break;
				default:
					if (configChanged.getKey().startsWith("muteNewAmbient"))
					{
						reloadScene();
					}
			}
		}
	}

	// Reload the scene to reapply ambient sounds
	private void reloadScene()
	{
		soundsToKeep.clear();
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.setGameState(GameState.LOADING);
			}
		});
	}

	@Subscribe(priority = -2) // priority -2 to run after music plugin
	public void onAmbientSoundEffectCreated(AmbientSoundEffectCreated ambientSoundEffectCreated)
	{
		WorldView worldView = ambientSoundEffectCreated.getWorldView();
		if (!worldView.isTopLevel())
			return;

		net.runelite.api.AmbientSoundEffect created = ambientSoundEffectCreated.getAmbientSoundEffect();
		removeSelectedSounds(created.getRandomSound());

		if (hasNoAmbientMutes())
			return;

		// some ambient sounds are created as -1 with no random sounds, just remove them imo.
		int soundId = created.getSoundEffectId();
		int[] randomSounds = getRandomSounds(created);
		boolean empty = randomSounds == null || randomSounds.length == 0;
		if ((soundId == -1 && empty) || ambientSoundsToMuteById.containsKey(soundId))
		{
			restoreSoundsToKeep();
		}
	}

	// In some areas the server sets a single ambient sound (client.getAmbientSound()) with its own random sounds
	@Subscribe(priority = -2) // priority -2 to run after music plugin
	public void onAmbientSoundChanged(AmbientSoundChanged ambientSoundChanged)
	{
		muteAmbientSounds();
	}

	private boolean hasNoAmbientMutes()
	{
		return ambientSoundsToMute.isEmpty() && newAmbientSoundsToMute.isEmpty();
	}

	@Nullable
	private static int[] getRandomSounds(net.runelite.api.AmbientSoundEffect ambientSoundEffect)
	{
		RandomSound randomSound = ambientSoundEffect.getRandomSound();
		return randomSound == null ? null : randomSound.getSoundEffectIds();
	}

	@Subscribe(priority = -2) // priority -2 to run after music plugin
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		GameState gameState = gameStateChanged.getGameState();

		// the scene is rebuilt on LOADING and the house objects spawn again if we are still in one
		if (gameState == GameState.LOADING)
		{
			isInPoh = false;
		}

		// on map load mute ambient sounds
		if (gameState == GameState.LOGGED_IN)
		{
			Player localPlayer = client.getLocalPlayer();
			if (localPlayer != null)
			{
				WorldPoint wp = localPlayer.getWorldLocation();
				currentPlayerRegionId = wp.getRegionID();
			}
			muteAmbientSounds();
		}
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		// on first login and on region changes we can mute the ambient sounds that are region based
		// this function might not be necessary tbh
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer != null)
		{
			WorldPoint wp = localPlayer.getWorldLocation();
			if (wp.getRegionID() != currentPlayerRegionId)
			{
				currentPlayerRegionId = wp.getRegionID();
				muteAmbientSounds();
			}
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		if (isInPoh)
		{
			return;
		}

		// The pet house (menagerie) objects only exist in a player owned house
		if (POH_PET_HOUSE_OBJECTS.contains(event.getGameObject().getId()))
		{
			isInPoh = true;
		}
	}

	// Check the ambient sounds currently being played and remove the ones that should be muted. That is both the
	// ambient sound effects and the ambient sound the server set, if there is one
	private void muteAmbientSounds()
	{
		if (!hasNoAmbientMutes() || !selectedSounds.isEmpty())
		{
			muteAmbientSoundEffects();
		}

		AmbientSoundComposition ambientSound = client.getAmbientSound();
		if (ambientSound == null)
		{
			return;
		}

		// the whole ambient sound goes if it is one of the selected new (location based) ambient sounds
		if (newAmbientSoundsToMute.contains(ambientSound.getId()))
		{
			client.setAmbientSound(null);
			return;
		}

		removeSelectedSoundsFromAmbientSound(ambientSound);
	}

	private void muteAmbientSoundEffects()
	{
		soundsToKeep.clear();
		Deque<net.runelite.api.AmbientSoundEffect> ambientSoundEffects = client.getTopLevelWorldView().getAmbientSoundEffects();

		for (net.runelite.api.AmbientSoundEffect ambientSoundEffect : ambientSoundEffects)
		{
			List<AmbientSoundEffect> mutedAmbientsSameID = ambientSoundsToMuteById
				.getOrDefault(ambientSoundEffect.getSoundEffectId(), Collections.emptyList());
			boolean muteSound = false;
			for (int i = 0; i < mutedAmbientsSameID.size() && !muteSound; i++)
			{
				int[] randomSounds = getRandomSounds(ambientSoundEffect);
				int[] randomSoundsToMatch = mutedAmbientsSameID.get(i).getRandomSoundEffects();

				// mute if id is the same and there are no random sounds
				if (randomSoundsToMatch.length == 0)
				{
					muteSound = true;
				}

				// mute only if the random sounds are similar to a selection
				if (randomSounds != null && randomSoundsToMatch.length != 0 && arraysLikeEnough(randomSounds, randomSoundsToMatch))
				{
					muteSound = true;
				}

				// if ambient sound is configured with a regionid
				int regionId = mutedAmbientsSameID.get(i).getRegionId();
				if (muteSound && regionId != -1)
				{
					// if current player region is not the same location as the defined regionid, don't mute the sound
					if (currentPlayerRegionId != regionId)
					{
						muteSound = false;
						break;
					}
				}
			}
			if (!muteSound)
			{
				// keep the effect, but take the "Muted Sounds" ids out of its random sounds
				removeSelectedSounds(ambientSoundEffect.getRandomSound());
				soundsToKeep.add(ambientSoundEffect);
			}
		}

		// ambient sounds with a -1 soundid with no other sounds with them can just be removed, it's probably a magic tree.
		if (config.muteMagicTrees())
		{
			soundsToKeep.removeIf(s -> s.getSoundEffectId() == -1
				&& (getRandomSounds(s) == null || getRandomSounds(s).length == 0));
		}

		restoreSoundsToKeep();
	}

	// Take the sounds listed in the "Muted Sounds" config out of the ambient sound the server set.
	// The client only accepts its own AmbientSoundComposition in setAmbientSound (it casts it), so a new
	// composition can't be made; the random sounds are edited in place and the edited composition is set again.
	private void removeSelectedSoundsFromAmbientSound(AmbientSoundComposition ambientSound)
	{
		if (selectedSounds.isEmpty())
		{
			return;
		}

		// the looping sounds can't be removed from the composition, so the whole ambient sound has to go
		if (anySelected(ambientSound.getSoundEffectIds()))
		{
			client.setAmbientSound(null);
			return;
		}

		List<RandomSound> randomSounds = ambientSound.getRandomSounds();
		if (randomSounds == null || randomSounds.isEmpty())
		{
			return;
		}

		boolean changed = false;
		List<RandomSound> emptied = new ArrayList<>();
		for (RandomSound randomSound : randomSounds)
		{
			int[] ids = randomSound.getSoundEffectIds();
			if (!anySelected(ids))
			{
				continue;
			}

			int[] remaining = Arrays.stream(ids).filter(id -> !selectedSounds.contains(id)).toArray();
			if (remaining.length == 0)
			{
				emptied.add(randomSound);
				continue;
			}
			// compositions are cached by the client, remember the original ids so they can be put back
			originalRandomSoundIds.putIfAbsent(randomSound, ids);
			randomSound.setSoundEffectIds(remaining);
			changed = true;
		}

		// a random sound with no ids left can't play anything, take it out of the composition
		if (!emptied.isEmpty())
		{
			originalRandomSoundLists.putIfAbsent(randomSounds, new ArrayList<>(randomSounds));
			randomSounds.removeAll(emptied);
			changed = true;
		}

		if (changed)
		{
			client.setAmbientSound(ambientSound);
		}
	}

	// Take the "Muted Sounds" ids out of an ambient sound effect's random sound, the looping sound keeps playing.
	// When nothing is left the ids are set to null, the client skips a null random sound but would crash on an empty one.
	private void removeSelectedSounds(@Nullable RandomSound randomSound)
	{
		if (randomSound == null || selectedSounds.isEmpty())
		{
			return;
		}

		int[] ids = randomSound.getSoundEffectIds();
		if (!anySelected(ids))
		{
			return;
		}

		int[] remaining = Arrays.stream(ids).filter(id -> !selectedSounds.contains(id)).toArray();
		// random sounds can be shared and cached by the client, remember the original ids so they can be put back
		originalRandomSoundIds.putIfAbsent(randomSound, ids);
		randomSound.setSoundEffectIds(remaining.length == 0 ? null : remaining);
	}

	private boolean anySelected(@Nullable int[] ids)
	{
		return ids != null && Arrays.stream(ids).anyMatch(id -> selectedSounds.contains(id));
	}

	// Put back the random sounds removed by removeSelectedSoundsFromAmbientSound
	private void restoreAmbientSoundRandomSounds()
	{
		originalRandomSoundIds.forEach(RandomSound::setSoundEffectIds);
		originalRandomSoundIds.clear();
		originalRandomSoundLists.forEach((list, original) ->
		{
			list.clear();
			list.addAll(original);
		});
		originalRandomSoundLists.clear();
	}

	// Clear the game's ambient sounds (mutes all of them), then add back the ones that are not black listed
	private void restoreSoundsToKeep()
	{
		Deque<net.runelite.api.AmbientSoundEffect> ambientSoundEffects = client.getTopLevelWorldView().getAmbientSoundEffects();
		ambientSoundEffects.clear();
		for (net.runelite.api.AmbientSoundEffect ambientSoundEffect : soundsToKeep)
		{
			ambientSoundEffects.addLast(ambientSoundEffect);
		}
	}

	// i can't be asked to find every single instance of 2184's ambient sound and all unique arrays
	// so let's find similar ones and include them as mutes
	private boolean arraysLikeEnough(int[] array1, int[] array2)
	{
		int total = 0;
		int totalSimilar = 0;

		for (int int1 : array1)
		{
			total++;
			for (int int2 : array2)
			{
				if (int1 == int2)
				{
					totalSimilar++;
				}
			}
		}

		return ((double) totalSimilar / total > 0.75);
	}

