	private void addGeneric(int... soundIds)
	{
		addGeneric(SoundEffectType.EITHER, soundIds);
	}

	private void addGeneric(SoundEffectType type, int... soundIds)
	{
		for (int soundId : soundIds)
		{
			soundEffects.add(new GenericSoundEffect(soundId, type));
		}
	}

	private void addAnimation(int soundId, int... animationIds)
	{
		for (int animationId : animationIds)
		{
			soundEffects.add(new AnimationSoundEffect(soundId, SoundEffectType.EITHER, animationId));
		}
	}

	private void addAmbient(int... soundIds)
	{
		for (int soundId : soundIds)
		{
			ambientSoundsToMute.add(new AmbientSoundEffect(soundId, SoundEffectType.AMBIENT));
		}
	}

	private void addAmbient(int soundId, int[] randomSoundIds)
	{
		ambientSoundsToMute.add(new AmbientSoundEffect(soundId, SoundEffectType.AMBIENT, randomSoundIds));
	}

	@Subscribe
	public void onAreaSoundEffectPlayed(AreaSoundEffectPlayed areaSoundEffectPlayed)
	{
		Actor source = areaSoundEffectPlayed.getSource();
		int soundId = areaSoundEffectPlayed.getSoundId();
		if (source != client.getLocalPlayer() && source instanceof Player)
		{
			if (config.muteOthersAreaSounds())
			{
				areaSoundEffectPlayed.consume();
			}
			else if (shouldMute(soundId, SoundEffectType.AREA_SOUND_EFFECT, source))
			{
				areaSoundEffectPlayed.consume();
			}
		}
		else if (source == null)
		{
			if (soundId == SoundEffectID.PET_WALKING_THUMP && client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1)
			{
				return;
			}
			if (soundId == SoundEffectID.SKELETON_THRALL_ATTACK && config.muteThralls())
			{
				areaSoundEffectPlayed.consume();
			}
			if (shouldMute(soundId, SoundEffectType.AREA_SOUND_EFFECT, null))
			{
				areaSoundEffectPlayed.consume();
			}
		}
		else if (shouldMute(soundId, SoundEffectType.AREA_SOUND_EFFECT, source))
		{
			areaSoundEffectPlayed.consume();
		}
	}

	@Subscribe
	public void onSoundEffectPlayed(SoundEffectPlayed soundEffectPlayed)
	{
		int soundId = soundEffectPlayed.getSoundId();
		if (shouldMute(soundId, SoundEffectType.SOUND_EFFECT, soundEffectPlayed.getSource()))
		{
			soundEffectPlayed.consume();
		}
	}

	@VisibleForTesting
	public boolean shouldMute(int soundId, SoundEffectType type, @Nullable Actor source)
	{
		if (selectedSounds.contains(soundId))
		{
			return true;
		}

		// everything a pet makes goes, no matter which sound it is
		if (mutePetFollowers && isFollower(source))
		{
			return true;
		}

		// pets in the player's house are not followers, they are level 0 npcs walking around
		// (only applied in a house so level 0 npcs elsewhere are untouched)
		if (mutePetFollowers && isInPoh && source instanceof NPC && source.getCombatLevel() == 0)
		{
			return true;
		}

		List<SoundEffect> candidates = soundEffectsById.get(soundId);
		if (candidates == null)
		{
			return false;
		}

		// sort the effects for this sound into generics and animations
		boolean hasGeneric = false;
		List<AnimationSoundEffect> animationSoundEffects = new ArrayList<>();
		for (SoundEffect s : candidates)
		{
			if (s.getSoundEffectType() != SoundEffectType.EITHER && s.getSoundEffectType() != type)
			{
				continue;
			}

			if (s instanceof GenericSoundEffect)
			{
				hasGeneric = true;
			}
			else if (s instanceof AnimationSoundEffect)
			{
				animationSoundEffects.add((AnimationSoundEffect) s);
			}
		}

		if (!hasGeneric && animationSoundEffects.isEmpty())
		{
			return false;
		}
		return animationSoundEffects.stream().noneMatch(s -> s.getAnimationID() == client.getLocalPlayer().getAnimation());
	}

	private static boolean isFollower(@Nullable Actor actor)
	{
		if (!(actor instanceof NPC))
		{
			return false;
		}

		NPCComposition composition = ((NPC) actor).getComposition();
		return composition != null && composition.isFollower();
	}

	// Every entry of the "Muted Sounds" config as a sound id. An entry is an id or a sound name,
	// anything else is ignored
	public Set<Integer> getSelectedSounds()
	{
		return resolveSoundIds(config.soundsToMute());
	}

	// Every entry of the "Muted Ambient Sounds" config as a sound id. An entry is an id or a sound name,
	// anything else is ignored
	public List<Integer> getGenericAmbientSounds()
	{
		return new ArrayList<>(resolveSoundIds(config.ambientSoundsToMute()));
	}

	// Every entry of the "Regional Muted Ambient Sounds" config as {regionId, soundId}. An entry is regionid:soundid
	// or regionid:soundname, anything else is ignored
	public List<int[]> getRegionalAmbientSounds()
	{
		List<int[]> returnValues = new ArrayList<>();
		for (String str : Text.fromCSV(config.ambientSoundsToMuteRegional()))
		{
			String[] parts = str.split(":");
			if (parts.length != 2)
			{
				continue;
			}

			Integer regionId = parseInt(parts[0]);
			Integer soundId = getSoundNames().resolveSoundId(parts[1]);
			if (regionId != null && soundId != null)
			{
				returnValues.add(new int[]{regionId, soundId});
			}
		}

		return returnValues;
	}

	public SoundNames getSoundNames()
	{
		if (soundNames == null)
		{
			soundNames = new SoundNames(gson);
		}
		return soundNames;
	}

	private Set<Integer> resolveSoundIds(@Nullable String configSounds)
	{
		if (configSounds == null || configSounds.isEmpty())
		{
			return Collections.emptySet();
		}

		Set<Integer> soundIds = new LinkedHashSet<>();
		for (String entry : Text.fromCSV(configSounds))
		{
			Integer soundId = getSoundNames().resolveSoundId(entry);
			if (soundId != null)
			{
				soundIds.add(soundId);
			}
		}

		return soundIds;
	}

	@Nullable
	private static Integer parseInt(String value)
	{
		try
		{
			return Integer.parseInt(value.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
