package com.brooklyn.annoyancemute;

import com.google.inject.Guice;
import com.google.inject.testing.fieldbinder.Bind;
import com.google.inject.testing.fieldbinder.BoundFieldModule;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.events.ConfigChanged;
import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;

@Slf4j
@RunWith(MockitoJUnitRunner.Silent.class)
public class AnnoyanceMuteTests
{
	@Mock
	@Bind
	private Client client;

	@Mock
	@Bind
	private RuneLiteConfig runeLiteConfig;

	@Mock
	@Bind
	private AnnoyanceMuteConfig config;

	@Inject
	private AnnoyanceMutePlugin plugin;

	@Before
	public void before()
	{
		Guice.createInjector(BoundFieldModule.of(this)).injectMembers(this);

		when(config.soundsToMute()).thenReturn("");
		when(config.ambientSoundsToMute()).thenReturn("");
		when(config.ambientSoundsToMuteRegional()).thenReturn("");
	}

	@Test
	public void muteWoodcutting()
	{
		when(config.muteWoodcutting()).thenReturn(true);

		ConfigChanged configChanged = new ConfigChanged();
		configChanged.setGroup("annoyancemute");
		configChanged.setKey("annoyancemute");
		plugin.onConfigChanged(configChanged);

		assertTrue(plugin.shouldMute(SoundEffectID.WOODCUTTING_CHOP, SoundEffectType.EITHER, null));
	}

	@Test
	public void muteDemons()
	{
		when(config.muteDemons()).thenReturn(false);

		ConfigChanged configChanged = new ConfigChanged();
		configChanged.setGroup("annoyancemute");
		configChanged.setKey("annoyancemute");
		plugin.onConfigChanged(configChanged);

		assertFalse(plugin.shouldMute(SoundEffectID.DEMON_ATTACK, SoundEffectType.EITHER, null));
	}

	@Test
	public void muteFollowerSounds()
	{
		when(config.mutePetSounds()).thenReturn(true);

		ConfigChanged configChanged = new ConfigChanged();
		configChanged.setGroup("annoyancemute");
		configChanged.setKey("annoyancemute");
		plugin.onConfigChanged(configChanged);

		NPCComposition followerComposition = mock(NPCComposition.class);
		when(followerComposition.isFollower()).thenReturn(true);
		NPC follower = mock(NPC.class);
		when(follower.getComposition()).thenReturn(followerComposition);

		NPCComposition otherComposition = mock(NPCComposition.class);
		when(otherComposition.isFollower()).thenReturn(false);
		NPC other = mock(NPC.class);
		when(other.getComposition()).thenReturn(otherComposition);

		// a sound that is not on any list is still muted when a pet makes it
		int unlistedSound = 1;
		assertTrue(plugin.shouldMute(unlistedSound, SoundEffectType.EITHER, follower));
		assertFalse(plugin.shouldMute(unlistedSound, SoundEffectType.EITHER, other));
		assertFalse(plugin.shouldMute(unlistedSound, SoundEffectType.EITHER, null));
	}

	@Test
	public void keepFollowerSoundsWhenPetsNotMuted()
	{
		when(config.mutePetSounds()).thenReturn(false);

		ConfigChanged configChanged = new ConfigChanged();
		configChanged.setGroup("annoyancemute");
		configChanged.setKey("annoyancemute");
		plugin.onConfigChanged(configChanged);

		NPCComposition followerComposition = mock(NPCComposition.class);
		when(followerComposition.isFollower()).thenReturn(true);
		NPC follower = mock(NPC.class);
		when(follower.getComposition()).thenReturn(followerComposition);

		assertFalse(plugin.shouldMute(1, SoundEffectType.EITHER, follower));
	}

	@Test
	public void muteTeleportOthers()
	{
		// when true/true like this, we only mute the sound when another player is doing it
		when(config.muteTeleport()).thenReturn(true);
		when(config.muteTeleportOthers()).thenReturn(true);

		ConfigChanged configChanged = new ConfigChanged();
		configChanged.setGroup("annoyancemute");
		configChanged.setKey("annoyancemute");
		plugin.onConfigChanged(configChanged);

		Player localPlayer = mock(Player.class);
		when(client.getLocalPlayer()).thenReturn(localPlayer);
		when(localPlayer.getAnimation()).thenReturn(7284);

		assertTrue(plugin.shouldMute(SoundEffectID.TELEPORT_VWOOP, SoundEffectType.EITHER, localPlayer));
	}

	@Test
	public void muteTeleportOthers2()
	{
		// when true/false like this, we only mute the sound when another player is doing it
		when(config.muteTeleport()).thenReturn(false);
		when(config.muteTeleportOthers()).thenReturn(true);

		ConfigChanged configChanged = new ConfigChanged();
		configChanged.setGroup("annoyancemute");
		configChanged.setKey("annoyancemute");
		plugin.onConfigChanged(configChanged);

		Player localPlayer = mock(Player.class);
		when(client.getLocalPlayer()).thenReturn(localPlayer);
		when(localPlayer.getAnimation()).thenReturn(7284);

		assertTrue(plugin.shouldMute(SoundEffectID.TELEPORT_VWOOP, SoundEffectType.EITHER, localPlayer));
	}

	@Test
	public void muteTeleports()
	{
		// when true/false like this, we will always mute the sounds
		when(config.muteTeleport()).thenReturn(true);
		when(config.muteTeleportOthers()).thenReturn(false);

		ConfigChanged configChanged = new ConfigChanged();
		configChanged.setGroup("annoyancemute");
		configChanged.setKey("annoyancemute");
		plugin.onConfigChanged(configChanged);

		Player localPlayer = mock(Player.class);
		when(client.getLocalPlayer()).thenReturn(localPlayer);
		when(localPlayer.getAnimation()).thenReturn(714);

		assertTrue(plugin.shouldMute(SoundEffectID.TELEPORT_VWOOP, SoundEffectType.EITHER, localPlayer));
	}

	@Test
	public void muteTeleports2()
	{
		// when true/false like this, we will always mute the sounds
		when(config.muteTeleport()).thenReturn(true);
		when(config.muteTeleportOthers()).thenReturn(false);

		ConfigChanged configChanged = new ConfigChanged();
		configChanged.setGroup("annoyancemute");
		configChanged.setKey("annoyancemute");
		plugin.onConfigChanged(configChanged);

		Player localPlayer = mock(Player.class);
		when(client.getLocalPlayer()).thenReturn(localPlayer);
		when(localPlayer.getAnimation()).thenReturn(9999); // new teleport animation id, same sound so it is muted because this configuration always mutes VWOOP sound

		assertTrue(plugin.shouldMute(SoundEffectID.TELEPORT_VWOOP, SoundEffectType.EITHER, localPlayer));
	}

	@Test
	public void teleportMakesNoise()
	{
		// when false/false like this, we won't mute
		when(config.muteTeleport()).thenReturn(false);
		when(config.muteTeleportOthers()).thenReturn(false);

		ConfigChanged configChanged = new ConfigChanged();
		configChanged.setGroup("annoyancemute");
		configChanged.setKey("annoyancemute");
		plugin.onConfigChanged(configChanged);

		Player localPlayer = mock(Player.class);
		when(client.getLocalPlayer()).thenReturn(localPlayer);
		when(localPlayer.getAnimation()).thenReturn(7284);

		assertFalse(plugin.shouldMute(SoundEffectID.TELEPORT_VWOOP, SoundEffectType.EITHER, localPlayer));
	}

	private void configChanged()
	{
		ConfigChanged configChanged = new ConfigChanged();
		configChanged.setGroup("annoyancemute");
		configChanged.setKey("soundsToMute");
		plugin.onConfigChanged(configChanged);
	}

	@Test
	public void mutedSoundsAcceptIdsAndNames()
	{
		when(config.soundsToMute()).thenReturn("chaos_elemental_madness_impact");
		configChanged();
		assertTrue(plugin.shouldMute(353, SoundEffectType.EITHER, null));

		when(config.soundsToMute()).thenReturn("353");
		configChanged();
		assertTrue(plugin.shouldMute(353, SoundEffectType.EITHER, null));

		// names are not case sensitive and entries can be mixed
		when(config.soundsToMute()).thenReturn("1, Chaos_Elemental_Madness_Impact");
		configChanged();
		assertTrue(plugin.shouldMute(353, SoundEffectType.EITHER, null));
		assertTrue(plugin.shouldMute(1, SoundEffectType.EITHER, null));
		assertFalse(plugin.shouldMute(354, SoundEffectType.EITHER, null));
	}

	@Test
	public void mutedSoundsIgnoreInvalidNames()
	{
		when(config.soundsToMute()).thenReturn("not_a_real_sound,,  ,353:,chaos_elemental_madness_impact");
		configChanged();
		assertTrue(plugin.shouldMute(353, SoundEffectType.EITHER, null));
		assertFalse(plugin.shouldMute(354, SoundEffectType.EITHER, null));
	}

	@Test
	public void mutedAmbientSoundsAcceptIdsAndNames()
	{
		when(config.ambientSoundsToMute()).thenReturn("chaos_elemental_madness_impact, 12, nope");
		assertEquals(Arrays.asList(353, 12), plugin.getGenericAmbientSounds());
	}

	@Test
	public void regionalMutedAmbientSoundsAcceptIdsAndNames()
	{
		when(config.ambientSoundsToMuteRegional()).thenReturn("4020:chaos_elemental_madness_impact,4021:12,4022:nope,nope:353,4023,1:2:3");
		List<int[]> regional = plugin.getRegionalAmbientSounds();
		assertEquals(2, regional.size());
		assertArrayEquals(new int[]{4020, 353}, regional.get(0));
		assertArrayEquals(new int[]{4021, 12}, regional.get(1));
	}
}

package com.brooklyn.annoyancemute.debug;

import com.brooklyn.annoyancemute.AnnoyanceMutePlugin;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.AmbientSoundComposition;
import net.runelite.api.AmbientSoundEffect;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.RandomSound;
import net.runelite.api.events.AmbientSoundChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.util.ColorUtil;

/**
 * Shows the ambient sounds the client currently has, which is the state AnnoyanceMutePlugin mutes (the plugin edits it
 * in place), so what is listed is what is left after muting. That is the ambient sound the server set
 * (client.getAmbientSound()) and the ambient sound effects of the scene (client.getTopLevelWorldView().getAmbientSoundEffects()).
 * <p>
 * Laid out like the ambient sounds overlay of the Visual Sounds plugin: each primary sound is followed by the random and
 * background sounds that go with it in brackets, and the text wraps to the width of the panel.
 * The lists are rebuilt after AnnoyanceMutePlugin has handled the same event, hence the priority.
 */
class AnnoyanceMuteAmbientSoundOverlay extends OverlayPanel
{
	private final static int PANEL_WIDTH = 250;
	private final static int PANEL_BORDER = 0;
	private final static int PRIORITY = -3; // after AnnoyanceMutePlugin, which uses -2 or the default
	private final static Color COLOR_HEADER = Color.YELLOW;
	private final static Color COLOR_PRIMARY = Color.WHITE;
	private final static Color COLOR_CONTAINER = Color.CYAN;
	private final static Color COLOR_SUB = new Color(0xA0A0A0);
	private final static Color COLOR_SUB_ALTERNATE = new Color(0xFFC864);

	private final Client client;
	private final AnnoyanceMuteDebugConfig config;
	private AnnoyanceMutePlugin plugin;

	// primary sound -> the random and background sounds that go with it
	private volatile Map<String, List<String>> ambientSounds = Collections.emptyMap();

	@Inject
	AnnoyanceMuteAmbientSoundOverlay(Client client, AnnoyanceMuteDebugConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.BOTTOM_LEFT);
		setMovable(true);
		setLayer(OverlayLayer.UNDER_WIDGETS);
		setPriority(PRIORITY_LOW);
		setPreferredSize(new Dimension(PANEL_WIDTH, 0));
	}

	void setMutePlugin(AnnoyanceMutePlugin plugin)
	{
		this.plugin = plugin;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showAmbientSounds())
		{
			return null;
		}

		List<LayoutableRenderableEntity> rows = panelComponent.getChildren();
		rows.add(LineComponent.builder()
			.left("Ambient sounds")
			.leftColor(COLOR_HEADER)
			.build());

		FontMetrics metrics = graphics.getFontMetrics();
		// the overlay is resizable and RuneLite restores the saved size, so wrap to the width it is drawn at
		Dimension panelSize = getPreferredSize();
		int maxTextWidth = (panelSize != null ? panelSize.width : PANEL_WIDTH) - PANEL_BORDER;
		int spaceWidth = metrics.stringWidth(" ");

		for (Map.Entry<String, List<String>> entry : ambientSounds.entrySet())
		{
			List<String> subs = entry.getValue();
			boolean hasSubs = !subs.isEmpty();

			// each token is { text with color tags, plain text to measure }
			List<String[]> tokens = new ArrayList<>();
			tokens.add(new String[]{
				ColorUtil.prependColorTag(entry.getKey(), COLOR_PRIMARY) + (hasSubs ? ColorUtil.prependColorTag(",", COLOR_CONTAINER) : ""),
				entry.getKey() + (hasSubs ? "," : "")});

			for (int i = 0; i < subs.size(); i++)
			{
				String open = i == 0 ? "[" : "";
				String close = i == subs.size() - 1 ? "]" : ",";
				Color color = i % 2 == 0 ? COLOR_SUB : COLOR_SUB_ALTERNATE;
				tokens.add(new String[]{
					ColorUtil.prependColorTag(open, COLOR_CONTAINER)
						+ ColorUtil.prependColorTag(subs.get(i), color)
						+ ColorUtil.prependColorTag(close, COLOR_CONTAINER),
					open + subs.get(i) + close});
			}

			// greedy wrap between tokens, a sound is never split across lines
			StringBuilder line = new StringBuilder();
			int lineWidth = 0;
			for (String[] token : tokens)
			{
				int width = metrics.stringWidth(token[1]);
				if (line.length() > 0 && lineWidth + spaceWidth + width > maxTextWidth)
				{
					rows.add(LineComponent.builder().left(line.toString()).build());
					line.setLength(0);
					lineWidth = 0;
				}
				if (line.length() > 0)
				{
					line.append(' ');
					lineWidth += spaceWidth;
				}
				line.append(token[0]);
				lineWidth += width;
			}
			if (line.length() > 0)
			{
				rows.add(LineComponent.builder().left(line.toString()).build());
			}
		}

		return super.render(graphics);
	}

	@Subscribe(priority = PRIORITY)
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		GameState gameState = gameStateChanged.getGameState();
		if (gameState == GameState.LOADING)
		{
			// the scene is being rebuilt, its ambient sounds are created again while it loads
			ambientSounds = Collections.emptyMap();
		}
		else if (gameState == GameState.LOGGED_IN)
		{
			refresh();
		}
	}

	@Subscribe(priority = PRIORITY)
	public void onAmbientSoundChanged(AmbientSoundChanged event)
	{
		refresh();
	}

	// AmbientSoundEffectCreated fires once per effect while a scene loads, so the lists are rebuilt on the next tick
	// instead, which is also when AnnoyanceMutePlugin handles a change of region
	@Subscribe(priority = PRIORITY)
	public void onGameTick(GameTick event)
	{
		refresh();
	}

	private void refresh()
	{
		if (!config.showAmbientSounds())
		{
			return;
		}

		// sets, because a scene has many identical ambient sound effects
		Map<String, Set<String>> sounds = new LinkedHashMap<>();

		AmbientSoundComposition ambientSound = client.getAmbientSound();
		if (ambientSound != null)
		{
			String name = plugin.getSoundNames().getAmbientSoundName(ambientSound.getId());
			Set<String> subs = sounds.computeIfAbsent((name != null ? name : "ambient_sound") + " (" + ambientSound.getId() + ")", k -> new LinkedHashSet<>());
			addLabels(subs, ambientSound.getSoundEffectIds());

			List<RandomSound> compositionRandomSounds = ambientSound.getRandomSounds();
			if (compositionRandomSounds != null)
			{
				for (RandomSound randomSound : compositionRandomSounds)
				{
					addLabels(subs, randomSound.getSoundEffectIds());
				}
			}
		}

		for (AmbientSoundEffect effect : client.getTopLevelWorldView().getAmbientSoundEffects())
		{
			RandomSound randomSound = effect.getRandomSound();

			// -1 is an effect that only has background sounds, which have no primary sound to go under
			String primary = effect.getSoundEffectId() != -1
				? AnnoyanceMuteSoundEffectOverlay.soundLabel(plugin.getSoundNames(), effect.getSoundEffectId())
				: "background (-1)";
			Set<String> subs = sounds.computeIfAbsent(primary, k -> new LinkedHashSet<>());
			if (randomSound != null)
			{
				addLabels(subs, randomSound.getSoundEffectIds());
			}
		}

		Map<String, List<String>> result = new LinkedHashMap<>();
		sounds.forEach((primary, subs) -> result.put(primary, new ArrayList<>(subs)));
		ambientSounds = result;
	}

	private void addLabels(Set<String> labels, int[] soundIds)
	{
		if (soundIds == null)
		{
			return;
		}
		for (int soundId : soundIds)
		{
			labels.add(AnnoyanceMuteSoundEffectOverlay.soundLabel(plugin.getSoundNames(), soundId));
		}
	}
}

package com.brooklyn.annoyancemute.debug;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(AnnoyanceMuteDebugConfig.GROUP)
public interface AnnoyanceMuteDebugConfig extends Config
{
	String GROUP = "annoyancemutedebug";

	@ConfigItem(
		keyName = "showAmbientSounds",
		name = "Ambient sounds overlay",
		description = "Shows the ambient sounds the client currently has, each primary sound followed by its random and background sounds in brackets",
		position = 0
	)
	default boolean showAmbientSounds()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showSoundEffects",
		name = "Game / area sounds overlay",
		description = "Shows the game and area sound effects as they play and whether they are muted",
		position = 1
	)
	default boolean showSoundEffects()
	{
		return true;
	}
}

package com.brooklyn.annoyancemute.debug;

import com.brooklyn.annoyancemute.AnnoyanceMutePlugin;
import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Annoyance Mute Debug",
	description = "Annoyance Mute Debug mode",
	tags = {"sound", "volume", "mute", "hub", "brooklyn", "pet", "stomp"}
)
public class AnnoyanceMutePluginDebug extends Plugin
{
	@Inject
	private EventBus eventBus;

	@Inject
	private PluginManager pluginManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private AnnoyanceMuteAmbientSoundOverlay ambientSoundOverlay;

	@Inject
	private AnnoyanceMuteSoundEffectOverlay soundEffectOverlay;

	@Provides
	AnnoyanceMuteDebugConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AnnoyanceMuteDebugConfig.class);
	}

	@Override
	protected void startUp()
	{
		// RuneLite only allows @PluginDependency on plugins that expose a public module, so look the plugin up instead
		AnnoyanceMutePlugin mutePlugin = pluginManager.getPlugins().stream()
			.filter(AnnoyanceMutePlugin.class::isInstance)
			.map(AnnoyanceMutePlugin.class::cast)
			.findFirst()
			.orElseThrow(() -> new IllegalStateException("Annoyance Mute is not loaded"));
		soundEffectOverlay.setMutePlugin(mutePlugin);
		ambientSoundOverlay.setMutePlugin(mutePlugin);
		overlayManager.add(ambientSoundOverlay);
		overlayManager.add(soundEffectOverlay);
		eventBus.register(ambientSoundOverlay);
		eventBus.register(soundEffectOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(ambientSoundOverlay);
		overlayManager.remove(soundEffectOverlay);
		eventBus.unregister(ambientSoundOverlay);
		eventBus.unregister(soundEffectOverlay);
	}
}

package com.brooklyn.annoyancemute.debug;

import com.brooklyn.annoyancemute.AnnoyanceMutePlugin;
import com.brooklyn.annoyancemute.SoundEffectType;
import com.brooklyn.annoyancemute.SoundNames;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.annotation.Nullable;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.AreaSoundEffectPlayed;
import net.runelite.api.events.SoundEffectPlayed;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

class AnnoyanceMuteSoundEffectOverlay extends OverlayPanel
{
	private final static int MAX_LINES = 10;
	private final static Color COLOR_SOUND_EFFECT = Color.WHITE;
	private final static Color COLOR_AREA_SOUND_EFFECT = Color.YELLOW;
	private final static Color COLOR_SILENT_SOUND_EFFECT = Color.GRAY;
	private final static Color COLOR_ALLOWED = Color.GREEN;
	private final static Color COLOR_CONSUMED = Color.RED;
	public static final String ALLOWED = "Allowed";
	public static final String CONSUMED = "Consumed";
	private final Client client;
	private final AnnoyanceMuteDebugConfig config;
	private AnnoyanceMutePlugin plugin;

	@Inject
	AnnoyanceMuteSoundEffectOverlay(Client client, AnnoyanceMuteDebugConfig config)
	{
		this.client = client;
		this.config = config;

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Game / Area Sounds")
			.leftColor(Color.CYAN)
			.build());

		setClearChildren(false);
		setPosition(OverlayPosition.TOP_LEFT);
	}

	void setMutePlugin(AnnoyanceMutePlugin plugin)
	{
		this.plugin = plugin;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showSoundEffects())
		{
			return null;
		}
		return super.render(graphics);
	}

	@Subscribe
	public void onSoundEffectPlayed(SoundEffectPlayed event)
	{
		int soundId = event.getSoundId();

		String text = "G: " + soundLabel(plugin.getSoundNames(), soundId) +
			" - S: " + sourceLabel(event.getSource()) +
			" - D: " + event.getDelay();

		String action = ALLOWED;
		Color actionColor = COLOR_ALLOWED;

		if (plugin.shouldMute(soundId, SoundEffectType.SOUND_EFFECT, event.getSource()))
		{
			action = CONSUMED;
			actionColor = COLOR_CONSUMED;
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left(text)
			.leftColor(COLOR_SOUND_EFFECT)
			.right(action)
			.rightColor(actionColor)
			.build());

		checkMaxLines();
	}

	@Subscribe
	public void onAreaSoundEffectPlayed(AreaSoundEffectPlayed event)
	{
		Color textColor = COLOR_AREA_SOUND_EFFECT;
		Color actionColor = COLOR_ALLOWED;

		int soundId = event.getSoundId();
		String text =
			"Id: " + soundLabel(plugin.getSoundNames(), soundId) +
				" - S: " + sourceLabel(event.getSource()) +
				" - L: " + event.getSceneX() + "," + event.getSceneY() +
				" - R: " + event.getRange() +
				" - D: " + event.getDelay();
		String action = ALLOWED;

		// Check if the player is within range to hear the sound
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer != null)
		{
			LocalPoint lp = localPlayer.getLocalLocation();
			if (lp != null)
			{
				int sceneX = lp.getSceneX();
				int sceneY = lp.getSceneY();
				int distance = Math.abs(sceneX - event.getSceneX()) + Math.abs(sceneY - event.getSceneY());
				if (distance > event.getRange())
				{
					textColor = COLOR_SILENT_SOUND_EFFECT;
					text = "SA: " + soundLabel(plugin.getSoundNames(), soundId);
				}
			}
		}

		if (plugin.shouldMute(soundId, SoundEffectType.AREA_SOUND_EFFECT, event.getSource()))
		{
			action = CONSUMED;
			actionColor = COLOR_CONSUMED;
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left(text)
			.leftColor(textColor)
			.right(action)
			.rightColor(actionColor)
			.build());

		checkMaxLines();
	}

	static String soundLabel(SoundNames soundNames, int soundId)
	{
		String name = soundNames.getSoundName(soundId);
		return name != null ? name + " (" + soundId + ")" : String.valueOf(soundId);
	}

	static String sourceLabel(@Nullable Actor source)
	{
		if (source == null)
		{
			return "<none>";
		}
		String id = source instanceof NPC ? "id " + ((NPC) source).getId() + ", " : "";
		return source.getName() + " (" + id + "cb " + source.getCombatLevel() + ")";
	}

	private void checkMaxLines()
	{
		while (panelComponent.getChildren().size() > MAX_LINES)
		{
			panelComponent.getChildren().remove(1);
		}
	}
}
